def restore_native_manager_parent(source):
    digest=lambda text:sha256(ast.unparse(ast.parse(text)).encode()).hexdigest()
    observed=digest(source)
    if observed==PARENT_MODULE:
        return source
    if observed!=CURRENT_MODULE:
        raise ValueError('Native manager differs from exact reviewed source delta')
    restored=source
    for current,parent in EDITS:
        if not current or restored.count(current)!=1:
            raise ValueError('Native manager exact source delta differs')
        restored=restored.replace(current,parent,1)
    if digest(restored)!=PARENT_MODULE:
        raise ValueError('Native manager complete legacy restoration differs')
    return restored
